import re

def isMatch(s, p):
    # Handle the case where the pattern is empty
    if not p:
        return not s

    # Check if the first character of the pattern is not the last character and matches the first character of the string
    first_match = bool(s) and p[0] in {s[0], '?', '*'}

    # If the pattern starts with '*', we have two possibilities:
    # 1. '*' matches zero characters, in which case we skip the '*' and the character after it in the pattern.
    # 2. '*' matches one or more characters, in which case we skip the first character of the string.
    if len(p) >= 2 and p[1] == '*':
        return (first_match and isMatch(s[1:], p)) or isMatch(s, p[2:])
    else:
        # If the pattern does not start with '*', we simply move to the next character in both the string and the pattern.
        return first_match and isMatch(s[1:], p[1:])

# Example usage:
